"use client"

// A three-state theme control: light, dark, and FOLLOW THE SYSTEM. Most toggles
// collapse that to a boolean, which quietly throws away the only setting a reader
// actually chose, and stops tracking when they change it at the OS.
//
// It is deliberately provider-agnostic: it takes the value and a setter, so it works
// with next-themes, with a hand-rolled context, or with nothing at all. Depending on
// a provider would make the item unusable to anyone who already has one.

import { Monitor, Moon, Sun } from "lucide-react"
import * as React from "react"
import "./theme-toggle.css"

export type Theme = "light" | "dark" | "system"

export const THEMES: { value: Theme; label: string; Icon: typeof Sun }[] = [
  { value: "light", label: "light", Icon: Sun },
  { value: "system", label: "system", Icon: Monitor },
  { value: "dark", label: "dark", Icon: Moon },
]

export interface ThemeToggleProps {
  /** The chosen theme, `system` included. NOT the resolved one: a control that shows
   *  `dark` when the reader picked `system` at night is reporting a fact they did not
   *  choose, and the next press then reads as a no-op.
   *
   *  Undefined while a provider is still resolving, which is a real render on every
   *  load: it falls back to `fallback` rather than showing nothing, because a
   *  three-way control with no option marked reads as broken, and a reader cannot
   *  tell it apart from one whose selected state is invisible. */
  value: Theme | undefined
  /** What an unresolved control shows. The provider's own default. */
  fallback?: Theme
  onChange: (theme: Theme) => void
  className?: string
}

export function ThemeToggle({
  value,
  fallback = "system",
  onChange,
  className,
}: ThemeToggleProps) {
  const shown = value ?? fallback
  // Real radios in a real fieldset, not three buttons wearing radio roles. One
  // setting with three values IS a radio group, and the browser then gives arrow-key
  // movement, the roving tab stop and the grouped announcement for free, correctly,
  // on every assistive technology rather than only the ones the ARIA was tested on.
  const name = React.useId()
  return (
    <fieldset className={`ag-theme-toggle${className ? ` ${className}` : ""}`}>
      <legend className="ag-sr-only">Theme</legend>
      {THEMES.map(({ value: v, label, Icon }) => (
        <label
          key={v}
          data-on={shown === v ? "" : undefined}
          title={label}
          className="ag-theme-toggle-option"
        >
          <input
            type="radio"
            name={name}
            value={v}
            checked={shown === v}
            onChange={() => onChange(v)}
            className="ag-sr-only"
          />
          <Icon size={14} aria-hidden />
          <span className="ag-sr-only">{label}</span>
        </label>
      ))}
    </fieldset>
  )
}

/* Three options in one track. The chosen one is a filled pill; the others are quiet
   until hovered, so the control reads as one setting rather than three buttons. */

/* A fieldset, so the reset has to be explicit: browsers give it a border, padding and
   a min-width of its content. */
.ag-theme-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.125rem;
  min-inline-size: 0;
  margin: 0;
  padding: 0.125rem;
  border: 1px solid var(--border);
  border-radius: 9999px;
  background: var(--sidebar);
}
.ag-theme-toggle-option {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 9999px;
  color: var(--muted-foreground);
  cursor: pointer;
  transition:
    color var(--dur-1, 150ms) var(--ease-out, ease),
    background-color var(--dur-1, 150ms) var(--ease-out, ease);
}
.ag-theme-toggle-option:hover {
  color: var(--foreground);
}
/* The chosen one INVERTS. A raised-surface treatment (background on a sidebar track)
   is the usual segmented-control look and it fails in the dark: --background 0.145 on
   a --sidebar 0.205 track is a sixtieth of lightness, darker than the track rather
   than raised, and the selection simply vanishes. Inverting cannot be subtle in the
   wrong direction, in either theme, at any contrast setting. */
.ag-theme-toggle-option[data-on] {
  color: var(--background);
  background: var(--foreground);
}
.ag-theme-toggle-option[data-on]:hover {
  color: var(--background);
}
/* The input is hidden, so the ring has to be drawn on the label that stands in for
   it, or keyboard focus lands somewhere invisible. */
.ag-theme-toggle-option:has(:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* The label is read aloud and never drawn: the icon carries it visually, and a
   `title` alone is not an accessible name on every screen reader. */
.ag-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

@media (prefers-reduced-motion: reduce) {
  .ag-theme-toggle-option {
    transition: none;
  }
}
